insert into public.events (id, slug, title, short_title, starts_at, ends_at, place_id, venue, address, description, program, capacity, price_public, price_member, premium_free, status, image, image_position, image_zoom, image_caption, featured, created_at) values
  ('5e500eef-1236-4703-a8ac-bc45335cd667', 'body-experience', 'BODY Expérience', 'BODY Expérience', '2026-10-19T13:00:00.000Z', '2026-10-19T17:00:00.000Z', null, 'Body Agency', 'Marrakech', 'Un après-midi rien que pour toi avec l’équipe de Body Agency : bilan, soins et conseils de coach, en petit comité.', '[{"time":"14 h","title":"Accueil et thé","text":"On se pose, on se présente."},{"time":"14 h 30","title":"Bilan personnalisé","text":"Un échange en tête-à-tête avec une coach."},{"time":"15 h 30","title":"Soins et ateliers","text":"Par petits groupes, à ton rythme."},{"time":"17 h 30","title":"Moment calme","text":"On partage ses impressions avant de repartir."}]'::jsonb, 15, 0, 0, true, 'published', 'body-agency.jpg', '18% 80%', '--z:1.7;--zo:22% 88%', 'BODY Expérience, Body Agency', false, '2026-09-15T09:00:00.000Z'),
  ('450e7a04-17f6-47fa-a04b-1e3c07a89120', 'lunch-raffine-networking', 'Lunch Raffiné & Networking', 'Lunch au Fer7', '2026-10-26T11:00:00.000Z', '2026-10-26T14:00:00.000Z', 'c79ac599-8db0-490d-a128-b42bf16dbd4a', 'Fer7', 'Golf, route d’Amizmiz', 'Une table face aux greens et aux palmiers, des saveurs asiatiques à partager, et des rencontres qui comptent.', '[{"time":"12 h","title":"Cercle d’ouverture","text":"Chacune se présente en une phrase : prénom, métier, depuis quand à Marrakech."},{"time":"12 h 30","title":"Speed networking en duo","text":"Huit minutes à deux, puis on change. Pas de badge, pas de pitch forcé."},{"time":"13 h 30","title":"Boîte à questions","text":"Les questions qu’on n’ose pas poser : visa, banque, école, clientèle."},{"time":"14 h 30","title":"Outils concrets","text":"Chacune repart avec trois contacts et une adresse à tester."}]'::jsonb, 12, 60, 50, false, 'published', 'lunch-fer7.jpg', '40% 50%', null, 'Fer7, table face au golf', true, '2026-09-20T09:00:00.000Z'),
  ('f2e1dc96-6c1b-420b-ae5c-f429e29269fd', 'tournoi-padel-feminin', 'Tournoi de padel féminin', 'Padel à Urban Padel', '2026-11-07T08:30:00.000Z', null, '13747a72-3bc8-44df-a165-44bc58b91f70', 'Urban Padel', 'Targa', 'Un tournoi en double, tous niveaux, dans la bonne humeur. On mélange les équipes pour que chacune rencontre de nouvelles joueuses.', '[{"time":"9 h 30","title":"Échauffement","text":"Les équipes sont tirées au sort."},{"time":"10 h","title":"Matchs de poules","text":"Des matchs courts, tout le monde joue."},{"time":"12 h","title":"Finale","text":"On encourage les finalistes."},{"time":"12 h 45","title":"Brunch au club-house","text":"Remise des prix et photo de groupe."}]'::jsonb, 8, 30, 25, false, 'published', 'padel.jpg', '50% 92%', '--z:1.9;--zo:50% 88%', 'Tournoi de padel, Urban Padel', false, '2026-09-10T09:00:00.000Z'),
  ('f4a0576c-86af-4aba-ae71-15d74969d7ff', 'diner-prive-terrajana', 'Dîner privé', 'Dîner à Terrajana', '2026-11-19T18:30:00.000Z', null, 'd41e503b-7be8-45ec-a05e-be5bf137a917', 'Terrajana', 'Route de l’Ourika', 'Une grande table dressée dans le jardin de Terrajana, un menu de saison et une soirée pour prendre le temps.', '[{"time":"19 h 30","title":"Apéritif au jardin","text":"Les présentations se font autour des lanternes."},{"time":"20 h 15","title":"Grande table","text":"Placement mélangé, pour rencontrer de nouvelles têtes."},{"time":"22 h","title":"Dessert et thé","text":"On termine doucement, sous les étoiles."}]'::jsonb, 20, 90, 75, false, 'published', 'diner-terrajana.jpg', '50% 58%', null, 'Dîner privé, Terrajana', false, '2026-09-25T09:00:00.000Z'),
  ('3e542b1b-d58a-45ad-a8e0-3ee9abd8eed6', 'family-day', 'Family Day', 'Family Day', '2026-11-29T10:00:00.000Z', '2026-11-29T15:00:00.000Z', '86a83087-b1ad-4a15-af26-33e663b13d60', 'The Ranch Morocco', 'Route de l’Ourika', 'Une journée à la ferme avec les enfants : poneys, pique-nique et ateliers.', '[]'::jsonb, 30, 40, 30, false, 'draft', null, null, null, null, false, '2026-10-05T09:00:00.000Z'),
  ('673ec6c2-49a4-481f-a547-d0ad4a092a83', 'chill-connect-hiver', 'Chill & Connect, édition d’hiver', 'Chill & Connect', '2026-12-12T15:00:00.000Z', null, null, null, null, 'Un après-midi doux pour se retrouver avant les fêtes.', '[]'::jsonb, 20, 40, 30, false, 'draft', 'chill-connect-groupe.jpg', '50% 60%', null, 'Chill & Connect, Palmeraie', false, '2026-10-07T09:00:00.000Z');
