-- Données d'exemple du Nomad Club (générées par scripts/seed-sql.mjs depuis src/lib/seed.ts).
-- Date de référence : mercredi 14 octobre 2026. À exécuter APRÈS toutes les migrations (supabase/migrations/*.sql).
-- Attention : ces comptes sont fictifs. Ne lancez pas ce fichier sur la base de production réelle.

begin;
select set_config('nc.trusted', 'on', true);

-- Comptes (auth.users) des profils d'exemple : le déclencheur crée les profils, complétés juste après.
on conflict (id) do nothing;

on conflict (id) do update set first_name = excluded.first_name, last_name = excluded.last_name, whatsapp = excluded.whatsapp, email = excluded.email, job = excluded.job, country = excluded.country, bio = excluded.bio, plan = excluded.plan, plan_ends_at = excluded.plan_ends_at, marrakech_since = excluded.marrakech_since, card_number = excluded.card_number, created_at = excluded.created_at;

-- Rôles cumulables (0003_socle.sql).
on conflict do nothing;









-- Organisations, journal et notifications (0003_socle.sql).






-- Lot 3 : offres complètes, fiches, codes, statistiques, abonnements des pros, invitations, positions (0005_partenaires.sql).
on conflict (id) do update set badge = excluded.badge, partner = excluded.partner, detail = excluded.detail, organization_id = excluded.organization_id, title = excluded.title, conditions = excluded.conditions, valid_from = excluded.valid_from, valid_until = excluded.valid_until, audience = excluded.audience, status = excluded.status, created_at = excluded.created_at;








select setval('public.card_number_seq', 700, false);
commit;
